import com.kobil.kssidp.wrapper.models.*
import com.kobil.wrapper.events.AuthenticationMode

fun activateMultiStep(idp: KssIdp, clientId: String, mode: AuthenticationMode,
    interaction: AdditionalDataCallback, completion: (KssIdpResultObject) -> Unit) {
    idp.activate(clientId, mode, null, interaction, completion)
}
fun loginMultiStep(idp: KssIdp, clientId: String, mode: AuthenticationMode,
    headers: HashMap<String, String>, interaction: AdditionalDataCallback,
    completion: (KssIdpResultObject) -> Unit) {
    idp.login(clientId, mode, headers, null, interaction, completion)
}
// AdditionalDataCallback.getAdditionalData receives requested DataModel fields,
// the KssIdpResult, and a continuation accepting HashMap<String,String>.
// Render requested fields; return input through that continuation exactly once.
// Retain the interaction until terminal result. Never log field values.

