import KSMasterController
import kssidp

func activateMultiStep(idp: KssIdpWrapper, clientId: String,
    mode: KSMAuthenticationMode, interaction: KssIdpDelegate,
    completion: @escaping KssIdpCompletion) {
    idp.activate(clientId: clientId, authMode: mode, appDelegate: interaction,
        completion: completion)
}
func loginMultiStep(idp: KssIdpWrapper, clientId: String,
    mode: KSMAuthenticationMode, headers: [String: String],
    interaction: KssIdpDelegate, completion: @escaping KssIdpCompletion) {
    idp.login(clientId: clientId, authMode: mode, appDelegate: interaction,
        headers: headers, completion: completion)
}
// Retain the delegate/UI for the complete interaction. Render each requested
// challenge and invoke its completion once. A displayed form is not success.
